class Contract(TypedDict):
    """One deployed contract: what its code is, what it looks like, and how it came to be.

    """

    address: str
    """The contract address, lowercase and `0x`-prefixed."""

    blockNumber: int
    """Block height of the current code record."""

    bytecodeSize: int
    """Size of the current runtime code in bytes."""

    bytecodeVariant: str
    """`legacy_raw`, `legacy_analyzed` or `eip7702` (a delegation designator, not code).

    """

    chainId: int
    """Chain id the contract is on. `1` is Ethereum mainnet."""

    codeFeatures: NotRequired[ContractCodeFeatures]
    """Opcode-level facts of the current code. Absent with `proxyFamily`: absent is not
    "none found".
    """

    codeHash: str
    """Keccak-256 hash of the current runtime code, `0x`-prefixed."""

    erc20Interface: Erc20Interface
    """Which of the four ERC-20 view functions the bytecode exposes, one by one. `isErc20`
    is `true` when all four are.
    """

    isEip1167Proxy: bool
    """`true` when the bytecode is an EIP-1167 minimal proxy."""

    isErc165: bool
    """`true` when the bytecode exposes `supportsInterface` (ERC-165)."""

    isErc20: bool
    """`true` when the bytecode exposes all four ERC-20 view functions; see
    `erc20Interface` for each one.
    """

    lifecycle: NotRequired[ContractLifecycle]
    """Deployment and destruction, when the lifecycle index has reached the address."""

    proxyConfidence: NotRequired[int]
    """Confidence of `proxyFamily`, 0 (none) to 3 (high). Absent with it."""

    proxyFamily: NotRequired[str]
    """Proxy pattern detected from this contract's own bytecode, for example
    `minimal_proxy`, `eip1967_impl`, `beacon`, `storage_delegate` (the code delegates to
    an address it reads from storage), `eip7702` (an account delegated by EIP-7702),
    `diamond_like`; `none` when no pattern was recognised, `unknown` when the analysis
    was inconclusive. The set grows as patterns are added. A classification of the code,
    not of a pointer: it can differ from `proxyFamily` on the proxy method's rows.
    Absent when the code has not been analysed for it.
    """

    proxyImplementation: NotRequired[str]
    """The implementation an EIP-1167 proxy delegates to. Absent otherwise; the proxy
    method lists implementations of every proxy kind.
    """

    selectorCount: int
    """Number of 4-byte selectors found as constants in the code: the contract's own
    functions, the selectors of functions it calls on other contracts and its custom
    errors together. Not the number of its functions.
    """


