class Counterparty(TypedDict):
    """One counterparty of the ranked address."""

    counterparty: str
    """The counterparty address, lowercase and `0x`-prefixed."""

    firstBlock: int
    """First block the two interacted in, within the window."""

    interactionTxCount: int
    """All transactions between the two, attempts included (reverted ones too)."""

    lastBlock: int
    """Last block the two interacted in, within the window."""

    receivedTxCount: int
    """Transactions in which the ranked address is the receiving side, by the same rule.

    """

    sentTxCount: int
    """Transactions in which the ranked address is the sending side of an interaction with
    the counterparty: it sent the top-level transaction (ETH or not), or it is the
    `from` of an internal ETH transfer or of a token `Transfer` event. NOT the
    transactions it signed: an event naming it as `from` counts here whoever emitted it.
    """

    succeededTxCount: int
    """The ranking key: transactions between the two that succeeded."""

    surfaceCounts: NotRequired[dict[str, int]]
    """Transactions per surface, for exactly the surfaces listed in `surfaces`. On the
    attempts scale (like `interactionTxCount`), and a transaction touching two surfaces
    counts on both — so the values explain where the relation lives, and do not add up
    to the ranking key. Absent when the source of this answer does not carry the
    breakdown (high-degree addresses served from the pre-built top list); absence means
    the breakdown was not computed, never zero.
    """

    surfaces: list[Surface]
    """On which surfaces the relation was observed: `external` (top-level transactions),
    `internal` (calls inside transactions), `token` (token transfers). A surface missing
    here had no interaction between the two.
    """

    tokenClasses: NotRequired[list[TokenClass]]
    """Which classes of token the `token` surface consists of: `fungible`, `nft`, or both.
    Present only when `surfaces` includes `token`. Both listed means the relation spans
    both classes; it does not say in what proportion.
    """


