class Proof(TypedDict):
    """The evidence behind one proven fact — an attribute of an address, or a relation
    between two addresses. Nothing here is summarised or ranked: the fields are the
    evaluator's own record, so a reader can check the claim rather than trust it.
    """

    attributeId: str
    """The attribute or relation id, `family:name`."""

    bindingVersions: NotRequired[dict[str, str]]
    """The data bindings the evaluation read, keyed by an opaque binding identifier (`ev:`
    + 12 hex characters). Each value is the version of what the binding was resolved to
    — a plain version such as `1.0.0` where the evaluator recorded one, otherwise an
    opaque identifier of the resolved source. Both identifiers are stable: the same
    binding, and the same source, carry the same identifier in every proof. Absent when
    the record does not state the bindings in a readable form.
    """

    chainId: int
    """Chain id the fact is about. `1` is Ethereum mainnet."""

    definitionVersion: str
    """Version of the definition the fact was evaluated against."""

    dependencyProofRefs: NotRequired[list[ProofDependencyRef] | None]
    """Other proofs this one depends on, one entry per proof. Empty for a fact that rests
    on no other proof; `null` when the record does not state them in a readable form.
    """

    evaluatedAt: int
    """When the evaluation ran, Unix time in seconds."""

    evaluatorVersion: str
    """Version of the evaluator that produced this proof, e.g. `1.0.0`. A different value
    on two proofs means they were produced by different evaluator releases.
    """

    factResults: NotRequired[ProofChecks | None]
    """The facts checked, each with its identifier (`fact_id`), the operator, the expected
    and the observed value. Where a check names the evidence it read, that reference is
    an opaque identifier (`ev:` + 12 hex characters), stable across proofs. `null` when
    the record does not state the checks in a readable form.
    """

    failureReasonCodes: NotRequired[list[str] | None]
    """Reason codes when `result` is not `pass`, each a `snake_case` string (for example
    `coverage_unknown`). Empty on a passing fact; `null` when the record does not state
    them in a readable form.
    """

    graphRevision: str
    """Revision of the knowledge graph's rule set that produced this proof: an opaque
    identifier, `rev:` + 12 hex characters. Stable — the same revision carries the same
    identifier in every proof; compare it for equality, it has no order.
    """

    negativeControlResults: NotRequired[ProofChecks | None]
    """Conditions that had to be false for the fact to hold, each with its identifier
    (`control_id`) and what was observed. `null` when the record does not state them in
    a readable form.
    """

    object: NotRequired[str]
    """The other end of a relation. Absent on an attribute proof."""

    proofHash: str
    """Digest of the proof record, `sha256:` + hex."""

    referenceBlock: int
    """Block the evidence was read at."""

    referenceBlockHash: str
    """Hash of that block, `0x`-prefixed — pins the evidence to one chain state."""

    result: str
    """Evaluation result. `pass` means the fact is proven."""

    selectedFamilyId: str
    """Which of the fact's alternative evidence families satisfied it."""

    snapshotId: str
    """Identifier of the chain snapshot the evaluation ran on."""

    sourceEvidenceRefs: NotRequired[list[EvidenceSource]]
    """Where the evidence was read from: one entry per evidence source, each an opaque
    identifier. Absent when the record does not state the sources in a readable form.
    """

    subject: str
    """The address the fact is about, lowercase and `0x`-prefixed."""

    value: NotRequired[str]
    """The fact's value, for facts that carry one."""


class ProofCheck(TypedDict):
    """One check of a proof. Its keys are written as the evaluation records them, in
    `snake_case`; the ones below are the common ones, and a check may carry others. In
    any key outside `fact_id`, `control_id`, `operator` and `evaluation`, a string is
    either a plain value (a `0x` hex value or a number) or an opaque evidence identifier
    (`ev:` + 12 hex characters, stable across proofs).
    """

    control_id: NotRequired[str]
    """The condition this check evaluates, on a negative control. Absent on a fact check.

    """

    evaluation: NotRequired[str]
    """What a negative control requires of its observation, for example `must_be_false`.

    """

    expected: NotRequired[Any]
    """The value the comparison expects, where the operator compares against one."""

    fact_id: NotRequired[str]
    """The fact this check evaluates, on a fact check. Absent on a negative control."""

    observed: NotRequired[Any]
    """The value observed in the evidence: a boolean, a number or a string."""

    operator: NotRequired[str]
    """The comparison applied, for example `exists`, `eq`, `neq`."""

    threshold: NotRequired[Any]
    """The bound the comparison applies, where the operator takes one (for example the
    minimum count of `exists`).
    """


# A reference to another proof that this one depends on.
ProofDependencyRef: TypeAlias = str | dict[str, Any]


