class ProxyImplementation(TypedDict):
    """One implementation a proxy has been observed delegating to, and whether it still
    does.
    """

    beacon: NotRequired[BeaconImplementations]
    """Only on a `storage_beacon` row, where `implementation` is the BEACON: the logic
    contracts the beacon handed to its proxies, read on the beacon itself. Absent on
    every other row, and when the beacon's history could not be read.
    """

    confidence: int
    """Confidence of the detection, 0 (none) to 3 (high)."""

    firstSeenBlock: int
    """First block the pointer was observed at."""

    implementation: str
    """The implementation address, lowercase and `0x`-prefixed. For a beacon proxy this is
    the BEACON: the logic contract behind it is resolved on the beacon, not here.
    """

    isSelfDelegation: bool
    """`true` when the proxy delegates to itself."""

    lastSeenBlock: int
    """Last block the pointer was observed at."""

    proxyFamily: str
    """Pattern classification of the proxy contract, for example `eip1967_impl`, `beacon`,
    `minimal_proxy`, `safe`; `none` or `unknown` when no pattern was recognised. The set
    grows as patterns are added.
    """

    slot: NotRequired[str]
    """The storage slot the pointer was read from, `0x`-prefixed. Absent for `eip1167`,
    where the pointer is in the code.
    """

    slotLastEvent: NotRequired[SlotEvent]
    """The last write observed on the pointer's slot: `upgrade` (a new implementation was
    written), `cleared` (the slot was emptied) or `unset` (the pointer was removed: zero
    written), with the block and transaction. Absent when no write to the slot is
    indexed.
    """

    source: str
    """How the implementation was found: `eip1167` (minimal-proxy bytecode),
    `storage_eip1967_impl` (the EIP-1967 implementation slot), `storage_beacon` (the
    EIP-1967 beacon slot), `storage_oz_v1` (the OpenZeppelin v1 slot),
    `storage_safe_singleton` (slot 0 of a Safe proxy: the singleton it delegates to).
    """

    supersededBy: NotRequired[str | None]
    """Whether this pointer has since been replaced. Three states, and each means something
    different: ABSENT — storage cannot say (the pointer lives in the code, or on a
    beacon upgraded elsewhere); `null` — no replacement observed, the pointer is
    current; an address — the pointer was replaced by it.
    """

    supersededByBlock: NotRequired[int]
    """Block of the replacement. Present exactly when `supersededBy` is an address."""


