class PublicMeta(TypedDict):
    """Response metadata."""

    asOfBlock: NotRequired[int]
    """The block height the answer is valid at — the same place on every method, whatever
    the body's own shape. Absent when the method's source states no block (a ranking
    recomputed daily, a set of proven facts): absence means "not stated", never
    "latest".
    """

    cached: bool
    """`true` when the answer came from the TraceFast response cache rather than being
    computed for this call. Cached answers are refreshed within minutes.
    """

    chain: str
    """Network the answer is about. `ethereum` for chain id `1`."""

    coverage: NotRequired[dict[str, int]]
    """Block heights that bound what this method can state, by name — for example the first
    block from which a derived fact is computed, or the last block a lagging fact has
    reached. Present only on methods whose coverage is bounded; each such method
    documents its keys. Re-read on every call, so a cached body carries current bounds.
    """

    docs: str
    """Documentation page of the method that produced this response."""

    timestamp: int
    """When this response was produced, Unix time in milliseconds."""


