class ReceivedCall(TypedDict):
    """One transaction that called the address — directly or from inside another contract.

    """

    blockNumber: int
    """Height of the block that includes the transaction."""

    callTypes: list[str]
    """The kinds of those frames: `call` and `staticcall` (the address was called),
    `delegatecall` and `callcode` (the address ran ANOTHER contract's code in its own
    context, as a proxy does), `selfdestruct` (a self-destruct sent its balance here).
    Other values may be added.
    """

    carriedValue: bool
    """At least one of those frames carried ETH."""

    failedFrames: int
