class TraceFrame(_TraceFrameKw):
    """One executed call frame of a transaction.

    Fields named like a Python keyword:

    - `from`: The caller of the frame, lowercase and `0x`-prefixed.
    """

    callPath: str
    """The frame's address in the call tree, as TraceFast encodes it: four hex characters
    per level, the root frame is `0000`.
    """

    callType: str
    """`call`, `callcode`, `delegatecall`, `staticcall`, `create`, `create2`,
    `selfdestruct`, `eoa_transfer`.
    """

    codeAddress: NotRequired[str]
    """The address whose code this frame runs. On a `delegatecall` this is the
    implementation while `to` stays the storage context — the PAIR is what makes a proxy
    call readable, which is why `to` does not change meaning. When this address is an
    account with an EIP-7702 delegation, the code that ran is its delegate's:
    `executedCodeAddress`. Absent where there is no callee code (`create`, `create2`,
    `selfdestruct`).
    """

    createdAddress: NotRequired[str]
    """The address a `create` / `create2` frame deployed."""

    delegation: NotRequired[FrameDelegation]
    """The authorization that set that delegation. Present exactly when
    `executedCodeAddress` is.
    """

    depth: int
    """Depth in the tree; `1` is the top-level call."""

    errorKind: NotRequired[str]
    """How it failed: `Revert`, `Panic`, `CustomError`, `OutOfGas`, …"""

    errorSelector: NotRequired[str]
    """The custom error's 4-byte selector — the ERROR selector, not `inputSelector`."""

    executedCodeAddress: NotRequired[str]
    """The code that actually ran when `codeAddress` is an account with an EIP-7702
    delegation in force at this frame: the delegate the account points at. Present only
    on such frames. Where the response's `delegatedCode.status` is `resolved`, a frame
    without it ran its own code; while it is `pending`, absence says nothing yet.
    """

    gas: str
    """Gas offered to the frame, as a decimal string."""

    gasUsed: str
    """Gas the frame consumed, as a decimal string."""

    initCodeHash: NotRequired[str]
    """Keccak-256 of the init code, `0x`-prefixed. Present only on a creating frame
    (`create`, `create2`).
    """

    inputHead: NotRequired[str]
    """The first 260 bytes of the frame's calldata, `0x`-hex. Present when calldata heads
    are included: always on the paged frames, and on the whole trace when
    `includeCalldata` is true.
    """

    inputSelector: NotRequired[str]
    """The called function's 4-byte selector."""

    inputSize: NotRequired[int]
    """Full length of the frame's calldata in BYTES. Compare it against 260, not against
    the hex string's length: the units differ. Present with `inputHead`.
    """

    order: int
    """Position in pre-order traversal of the call tree; `0` is the transaction's own
    top-level call.
    """

    outputHead: NotRequired[str]
    """The first 260 bytes of the frame's output, `0x`-hex. Present with `inputHead`."""

    outputSize: NotRequired[int]
    """Full length of the frame's output in BYTES. Compare it against 260, not against the
    hex string's length. Present with `inputHead`.
    """

    parentPath: NotRequired[str]
    """The `callPath` of the frame that made this call. Absent on the root frame."""

    revertData: NotRequired[str]
    """The raw ABI revert payload, `0x`-prefixed hex. It may be truncated —
    `revertDataTruncated` says when, and a clipped payload decodes into a plausible but
    wrong argument list, so check the flag before decoding. Absent when there is no
    payload to state.
    """

    revertDataSize: NotRequired[int]
    """Full length of the revert payload in BYTES, whether or not `revertData` is
    truncated. Absent with `revertData`.
    """

    revertDataTruncated: NotRequired[bool]
    """`true` when `revertData` is shorter than the payload (`revertDataSize`). Absent with
    `revertData`.
    """

    revertDecodeStatus: NotRequired[str]
    """Why `revertReason` is what it is: `decoded`, `undecodable` (a payload is present but
    no name was found) or `absent` (no payload to decode). An empty reason is ambiguous
    three ways, and this field is what separates them.

    Named apart from the event decoder's `decodeStatus` on purpose: that vocabulary
    describes event-decode confidence and the two appear in one response.
    """

    revertReason: NotRequired[str]
    """The decoded revert reason, or the custom error's name when its selector is known.

    """

    salt: NotRequired[str]
    """The `create2` salt, 32 bytes, `0x`-prefixed. Present only on a `create2` frame.

    """

    selfdestructBeneficiary: NotRequired[str]
    """Who received the balance of a `selfdestruct` frame."""

    status: str
    """`success`, `reverted` or `halted` — the FRAME's own outcome, which on a caught
    revert differs from the transaction's.
    """

    to: NotRequired[str]
    """The frame's target. Absent on a contract creation."""

    valueWei: str
    """Value this frame moved, in wei, as a decimal string."""


