    to: NotRequired[str]
    """Recipient. Absent for a contract creation."""

    txIndex: int
    """Position of the transaction within its block, from `0`."""

    txType: int
    """Transaction type (0 legacy, 1 EIP-2930, 2 EIP-1559, 3 EIP-4844, 4 EIP-7702)."""

    valueWei: str
    """Value transferred, wei, decimal string."""


